for (const c of comments) {
  const li = document.createElement('li');
  const b = document.createElement('b');
  b.textContent = c.author;
  li.append(b, ': ' + c.text); // strings appended as text nodes
  list.append(li);
}
```

questions.prompt:
This endpoint powers a "link preview" feature on a server running in AWS:

```js
app.get('/preview', async (req, res) => {
  const r = await fetch(req.query.url);
  const html = await r.text();
  res.json({ title: html.match(/<title>(.*?)<\/title>/)?.[1] });
});
```

What is the vulnerability, what's the worst-case impact, and how do you fix it robustly?

questions.answer:
```js
const dns = require('node:dns/promises');
const net = require('node:net');

function isPrivate(ip) {
  if (net.isIPv6(ip)) return ip === '::1' || /^f[cd]/i.test(ip) || /^fe80/i.test(ip) || ip.startsWith('::ffff:');
  const [a, b] = ip.split('.').map(Number);
  return a === 10 || a === 127 || a === 0 ||
    (a === 172 && b >= 16 && b <= 31) || (a === 192 && b === 168) || (a === 169 && b === 254);
}

async function checkUrl(raw) {
  const url = new URL(raw);
  if (url.protocol !== 'https:') throw new Error('https only');
  const addrs = await dns.lookup(url.hostname, { all: true });
  if (addrs.some((a) => isPrivate(a.address))) throw new Error('blocked address');
  return addrs[0].address; // connect to THIS ip (pin it), don't re-resolve
}
// also: redirect: 'manual' and re-check each hop, short timeout, max body size
```
